const Dropdown = ({ label, items }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const onClick = (e) => {if (ref.current && !ref.current.contains(e.target)) setOpen(false);};
    document.addEventListener('click', onClick);
    return () => document.removeEventListener('click', onClick);
  }, []);
  useEffect(() => {window.lucide && window.lucide.createIcons();}, [open]);
  return (
    <div className={`dropdown ${open ? 'open' : ''}`} ref={ref}>
      <button aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {label}
        <i data-lucide="chevron-down" style={{ width: 12, height: 12 }} />
      </button>
      <div className="dropdown-panel" role="menu" aria-label={label}>
        {items.map((it) =>
        <a key={it.href} className="dropdown-item" href={it.href} role="menuitem" {...it.external ? { target: '_blank', rel: 'noopener noreferrer' } : {}}>
            <div className="ico"><i data-lucide={it.icon} style={{ width: 16, height: 16 }} /></div>
            <div>
              <b>{it.title}</b>
              <span>{it.desc}</span>
            </div>
          </a>
        )}
      </div>
    </div>);

};

const MegaDropdown = ({ label, groups, viewAllHref, viewAllLabel, twoCol = false }) => {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  useEffect(() => {
    const onClick = (e) => {if (ref.current && !ref.current.contains(e.target)) setOpen(false);};
    document.addEventListener('click', onClick);
    return () => document.removeEventListener('click', onClick);
  }, []);
  useEffect(() => {window.lucide && window.lucide.createIcons();}, [open]);
  return (
    <div className={`mega-dropdown ${open ? 'open' : ''}`} ref={ref}>
      <button aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen((o) => !o)}>
        {label}
        <i data-lucide="chevron-down" style={{ width: 12, height: 12 }} />
      </button>
      <div className="mega-panel" role="menu" aria-label={label}>
        <div className="mega-cols" style={{ gridTemplateColumns: `repeat(${groups.length}, 1fr)` }}>
          {groups.map((g) =>
          <div key={g.group} className="mega-col">
              <div className="mega-col-head">{g.group}</div>
              <div className={twoCol ? 'mega-col-items mega-col-items--2' : 'mega-col-items'}>
                {g.items.map((it) =>
              <a key={it.href} href={it.href} className="mega-item" role="menuitem">
                  <i data-lucide={it.icon} className="mega-item-ico" />
                  <span>{it.title}</span>
                </a>
              )}
              </div>
            </div>
          )}
        </div>
        {viewAllHref &&
        <div className="mega-footer-row">
            <a href={viewAllHref} className="link-arrow">
              {viewAllLabel} <i data-lucide="arrow-right" style={{ width: 12, height: 12 }} className="arrow" />
            </a>
          </div>
        }
      </div>
    </div>);

};

const LucideIcon = ({ name, className = '', size = 16 }) => {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || !window.lucide) return;
    el.replaceChildren();
    const i = document.createElement('i');
    i.setAttribute('data-lucide', name);
    i.style.width = `${size}px`;
    i.style.height = `${size}px`;
    el.appendChild(i);
    window.lucide.createIcons({ root: el });
  }, [name, size]);
  return (
    <span
      ref={ref}
      className={className}
      style={{ width: size, height: size, display: 'inline-flex', alignItems: 'center', justifyContent: 'center' }}
      aria-hidden="true"
    />
  );
};

const MobileNavItem = ({ href, icon, title, external, stagger = 0 }) =>
  <a
    href={href}
    className="nav-mobile-item"
    style={{ '--stagger': stagger }}
    {...external ? { target: '_blank', rel: 'noopener noreferrer' } : {}}
  >
    {icon ? <span className="nav-mobile-chip"><LucideIcon name={icon} size={18} /></span> : null}
    <span className="nav-mobile-item-label">{title}</span>
  </a>;

const MobileNavGroups = ({ groups, viewAllHref, viewAllLabel }) => {
  let stagger = 0;
  return (
    <>
      {groups.map((g) => {
        const headStagger = stagger++;
        return (
          <div key={g.group} className="nav-mobile-subgroup">
            <div className="nav-mobile-subhead" style={{ '--stagger': headStagger }}>{g.group}</div>
            <div className="nav-mobile-grid">
              {g.items.map((it) => {
                const itemStagger = stagger++;
                return <MobileNavItem key={it.href} {...it} stagger={itemStagger} />;
              })}
            </div>
          </div>
        );
      })}
      {viewAllHref ?
        <a href={viewAllHref} className="link-arrow" style={{ '--stagger': stagger }}>
          {viewAllLabel} <LucideIcon name="arrow-right" size={14} className="arrow" />
        </a> :
        null}
    </>
  );
};

